<!doctype html><html lang="en" class="rag-html"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover"><meta name="theme-color" content="#202123"><title>RAG Library · Local AI</title><link rel="stylesheet" href="assets/app.css?v=60"><link rel="stylesheet" href="assets/app-ui.css?v=2"><link rel="stylesheet" href="assets/app-features.css?v=1"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700&display=swap"><link rel="stylesheet" href="https://fonts.googleapis.com/icon?family=Material+Icons+Round"></head><body class="rag-body">
