      <form id="uploadForm" class="upload-box"><label class="rag-drop-label" for="ragFile"><span class="rag-upload-symbol"><span class="material-icons-round">upload_file</span></span><strong>Choose a document to upload</strong><small>Supported formats: TXT, MD, CSV, JSON, XML, HTML, LOG, DOCX, XLSX and PPTX</small></label><input id="ragFile" type="file" name="file" accept=".txt,.md,.csv,.json,.xml,.html,.htm,.log,.docx,.xlsx,.pptx" aria-label="Choose document file" required><button class="primary" type="submit"><span class="material-icons-round">add</span> Upload and queue</button></form>
