<div id="toast" class="toast"></div><script>window.APP={csrf:<?=json_encode($csrf)?>};</script>
<script>
(()=>{'use strict';const $=s=>document.querySelector(s),csrf=window.APP.csrf,PER_PAGE=50;let allItems=[],page=1,wasActive=false,hideTimer=null,searchTerm='',statusFilter='all',openInfoId=null;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const toast=t=>{const e=$('#toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',3200)};async function post(action,data={}){const f=new FormData();f.append('_csrf',csrf);Object.entries(data).forEach(([k,v])=>f.append(k,v));const r=await fetch('api.php?action='+action,{method:'POST',body:f});const j=await r.json();if(!r.ok||j.error)throw Error(j.error||'Request failed');return j}const statusLabel=s=>({queued:'Queued',extracting:'Extracting',chunking:'Chunking',embedding:'Embedding',completed:'Indexed',failed:'Error',cancelled:'Cancelled'}[s]||s);function renderPage(){const filtered=allItems.filter(d=>(!searchTerm||String(d.name||'').toLowerCase().includes(searchTerm))&&(statusFilter==='all'||d.status===statusFilter));const total=Math.max(1,Math.ceil(filtered.length/PER_PAGE));page=Math.min(page,total);const items=filtered.slice((page-1)*PER_PAGE,page*PER_PAGE);$('#documents').innerHTML=items.map(d=>`<div class="docrow rag-docrow"><div class="rag-doc-main"><b>${esc(d.name)}</b></div><div class="rag-doc-actions"><button class="rag-icon-btn rag-info-btn" data-info="${esc(d.id)}" title="Document information" aria-label="Document information" aria-expanded="${String(openInfoId)===String(d.id)}"><span class="material-icons-round">info_outline</span></button>${(['queued','extracting','chunking','embedding'].includes(d.status)&&Number(d.pending_vectors||0)===0)?'':`<button class="rag-icon-btn delete" data-del="${d.id}" title="Delete document" aria-label="Delete document"><span class="material-icons-round">delete</span></button>`}</div>${String(openInfoId)===String(d.id)?`<div class="rag-info-popover" role="dialog" aria-label="Document information"><div class="rag-info-popover-title">Document details</div><div><span>File size</span><b>${(Number(d.size_bytes)/1024).toFixed(1)} KB</b></div><div><span>Uploaded</span><b>${esc(d.created_at||'—')}</b></div><div><span>Chunks</span><b>${Number(d.chunks||0).toLocaleString()}</b></div><div><span>Status</span><b class="rag-status ${d.status==='failed'?'is-error':d.status==='completed'?'is-done':''}">${esc(statusLabel(d.status))}</b></div>${d.last_error?`<p class="rag-info-error">${esc(d.last_error)}</p>`:''}</div>`:''}</div>`).join('')||'<div class="rag-empty"><span class="material-icons-round">folder_open</span><strong>'+((searchTerm||statusFilter!=='all')?'No matching documents':'Your library is empty')+'</strong><small>'+((searchTerm||statusFilter!=='all')?'Try another search or status filter.':'Upload your first document to start building your knowledge library.')+'</small></div>';const nav=$('#ragPagination');nav.hidden=filtered.length<=PER_PAGE;$('#ragPageInfo').textContent=`Page ${page}/${total} · ${filtered.length} documents`;$('#ragPrev').disabled=page<=1;$('#ragNext').disabled=page>=total;document.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this document from the library? Chunks shared with other documents will be retained.'))try{await post('document_delete',{id:b.dataset.del});await load();toast('Document deleted; unused vectors queued for cleanup')}catch(e){toast(e.message)}})}function positionInfoPopover(){const pop=document.querySelector('#documents .rag-info-popover');if(!pop)return;const btn=Array.from(document.querySelectorAll('#documents [data-info]')).find(x=>String(x.dataset.info)===String(openInfoId));if(!btn)return;const r=btn.getBoundingClientRect(),w=pop.offsetWidth,h=pop.offsetHeight,pad=12;let left=Math.min(window.innerWidth-w-pad,Math.max(pad,r.right-w));let top=r.bottom+8;if(top+h>window.innerHeight-pad)top=r.top-h-8;top=Math.max(pad,Math.min(top,window.innerHeight-h-pad));pop.style.position='fixed';pop.style.left=left+'px';pop.style.top=top+'px';pop.style.right='auto';pop.style.bottom='auto';pop.style.transform='none'}function updateProgress(items,sm){const active=items.filter(d=>['queued','extracting','chunking','embedding'].includes(d.status));const ob=(sm.outbox||[]).reduce((n,x)=>n+(['pending','processing'].includes(x.status)?Number(x.total):0),0);const running=active.length>0||ob>0;const el=$('#ragWorkerProgress');if(running){wasActive=true;if(hideTimer){clearTimeout(hideTimer);hideTimer=null}el.hidden=false;const current=active[0];const label=current?statusLabel(current.status):'Synchronizing vectors';$('#ragProgressTitle').textContent='RAG Worker is processing';$('#ragProgressState').textContent=label;$('#ragProgressDetail').textContent=active.length+' documents queued/processing · '+ob+' vectors queued or synchronizing';el.classList.remove('is-complete')}else if(wasActive){wasActive=false;el.classList.add('is-complete');$('#ragProgressState').textContent='Completed';$('#ragProgressDetail').textContent='All monitored tasks have completed.';hideTimer=setTimeout(()=>{el.hidden=true;el.classList.remove('is-complete')},3000)}else{el.hidden=true}$('#workerNote').textContent=running?active.length+' tasks queued or processing.':'No pending tasks.'}async function load(){try{const r=await fetch('api.php?action=documents',{cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Could not load library');allItems=j.items||[];const sm=j.summary||{},jobs=Object.fromEntries((sm.jobs||[]).map(x=>[x.status,Number(x.total)])),ob=Object.fromEntries((sm.outbox||[]).map(x=>[x.status,Number(x.total)]));const chunkCount=Number(sm.chunks||allItems.reduce((n,d)=>n+Number(d.chunks||0),0));$('#ragMetricDocs').textContent=allItems.length.toLocaleString();$('#ragMetricChunks').textContent=chunkCount.toLocaleString();$('#ragMetricFailed').textContent=Number(jobs.failed||0).toLocaleString();$('#ragMetricPending').textContent=Number(ob.pending||0).toLocaleString();renderPage();updateProgress(allItems,sm)}catch(e){toast(e.message);$('#workerNote').textContent='Could not read queue status.'}}$('#documents').addEventListener('scroll',()=>{if(openInfoId!==null){openInfoId=null;const p=document.querySelector('#documents .rag-info-popover');if(p)p.remove()}},{passive:true});$('#documents').addEventListener('click',e=>{const info=e.target.closest('[data-info]');if(info){e.stopPropagation();const id=info.dataset.info;openInfoId=String(openInfoId)===String(id)?null:id;renderPage();if(openInfoId!==null)positionInfoPopover();return}if(e.target.closest('.rag-info-popover')){e.stopPropagation();return}if(!e.target.closest('[data-del]')&&openInfoId!==null){openInfoId=null;renderPage()}});document.addEventListener('click',e=>{if(openInfoId!==null&&!e.target.closest('#documents')){openInfoId=null;renderPage()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&openInfoId!==null){openInfoId=null;renderPage()}});$('#ragSearch').addEventListener('input',e=>{searchTerm=e.target.value.trim().toLowerCase();page=1;renderPage()});$('#ragStatusFilter').addEventListener('change',e=>{statusFilter=e.target.value;page=1;renderPage()});$('#ragPrev').onclick=()=>{page=Math.max(1,page-1);renderPage()};$('#ragNext').onclick=()=>{page++;renderPage()};$('#uploadForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const f=new FormData(e.target);f.append('_csrf',csrf);try{const r=await fetch('api.php?action=upload',{method:'POST',body:f}),j=await r.json();if(!r.ok||j.error)throw Error(j.error||'Upload failed');toast(j.message||'Document received');if(!j.duplicate)e.target.reset();page=1;await load()}catch(err){toast(err.message)}finally{b.disabled=false}};$('#rebuildVectors').onclick=async()=>{if(!confirm('Queue all canonical chunks for embedding and Qdrant upsert?'))return;try{const j=await post('rag_vector_rebuild');toast(j.message);await load()}catch(e){toast(e.message)}};load();setInterval(load,2000)})();</script></body></html>
